import re
with open('doc/Laboratory.md', 'r') as f:
    content = f.read()

# Extract all patient-creatinine pairs with context about whether it's abnormal
lines = content.split('\n')
patient_data = {}

for i, line in enumerate(lines):
    # Look for patient ID and creatinine value
    match = re.search(r'patient\s+(\d+).*?creatinine.*?(\d+\.\d+)', line, re.IGNORECASE)
    if match:
        pid = match.group(1)
        cret = float(match.group(2))

        # Check if this entry is marked as abnormal/elevated
        is_abnormal = False
        context_lower = line.lower()
        if any(word in context_lower for word in ['elevated', 'significantly elevated', 'high', 'abnormal', 'impaired', 'compromised', 'renal stress']):
            is_abnormal = True

        if pid not in patient_data:
            patient_data[pid] = {'creatinine': cret, 'is_abnormal': is_abnormal}
        else:
            # Keep the most recent or highest value if already exists
            if cret > patient_data[pid]['creatinine']:
                patient_data[pid] = {'creatinine': cret, 'is_abnormal': is_abnormal}

print(f"Total unique patients: {len(patient_data)}")

# Find abnormal patients
abnormal_patients = [(pid, data) for pid, data in patient_data.items() if data['is_abnormal']]
print(f"Abnormal patients: {len(abnormal_patients)}")
for pid, data in abnormal_patients:
    print(f"Patient {pid}: creatinine={data['creatinine']}, abnormal={data['is_abnormal']}")

